ALTER TABLE "inventory_ledger" ADD CONSTRAINT "inventory_ledger_movement_check" CHECK (("inventory_ledger"."movement" in ('OPENING', 'PURCHASE_IN', 'REPAIR_IN', 'DELIVERY_IN', 'RETURN_IN', 'TRANSFER_IN', 'ADJUST_IN') and "inventory_ledger"."quantity" > 0 and "inventory_ledger"."location_id" is not null) or ("inventory_ledger"."movement" in ('REPAIR_OUT', 'DELIVERY_OUT', 'RETURN_OUT', 'TRANSFER_OUT', 'SALE_OUT', 'ADJUST_OUT') and "inventory_ledger"."quantity" < 0 and "inventory_ledger"."location_id" is not null) or ("inventory_ledger"."movement" = 'REVALUE' and "inventory_ledger"."quantity" = 0 and "inventory_ledger"."location_id" is null));--> statement-breakpoint
ALTER TABLE "stock_adjustment" ADD CONSTRAINT "stock_adjustment_revalue_check" CHECK (("stock_adjustment"."kind" <> 'REVALUE' or "stock_adjustment"."related_document_code" is not null)
        and (("stock_adjustment"."source_receipt_id" is null and "stock_adjustment"."recorded_trip_cost" is null and "stock_adjustment"."corrected_trip_cost" is null)
          or ("stock_adjustment"."kind" = 'REVALUE' and "stock_adjustment"."source_receipt_id" is not null and "stock_adjustment"."recorded_trip_cost" >= 0 and "stock_adjustment"."corrected_trip_cost" >= 0)));--> statement-breakpoint
ALTER TABLE "stock_adjustment" ADD CONSTRAINT "stock_adjustment_kind_check" CHECK ("stock_adjustment"."kind" in ('ADJUSTMENT', 'OPENING', 'REVALUE'));--> statement-breakpoint
ALTER TABLE "stock_adjustment_line" ADD CONSTRAINT "stock_adjustment_line_type_check" CHECK ("stock_adjustment_line"."line_type" in ('QUANTITY', 'CONDITION', 'LOCATION', 'OPENING', 'VALUE'));--> statement-breakpoint
ALTER TABLE "stock_adjustment_line" ADD CONSTRAINT "stock_adjustment_line_shape_check" CHECK (("stock_adjustment_line"."line_type" = 'QUANTITY' and "stock_adjustment_line"."quantity" <> 0 and "stock_adjustment_line"."to_condition" is null and "stock_adjustment_line"."to_location_id" is null and "stock_adjustment_line"."location_id" is not null and "stock_adjustment_line"."value_delta" is null)
        or ("stock_adjustment_line"."line_type" = 'CONDITION' and "stock_adjustment_line"."quantity" > 0 and "stock_adjustment_line"."to_condition" is not null and "stock_adjustment_line"."to_condition" <> "stock_adjustment_line"."condition" and "stock_adjustment_line"."to_location_id" is null and "stock_adjustment_line"."location_id" is not null and "stock_adjustment_line"."value_delta" is null)
        or ("stock_adjustment_line"."line_type" = 'LOCATION' and "stock_adjustment_line"."quantity" > 0 and "stock_adjustment_line"."to_location_id" is not null and "stock_adjustment_line"."to_location_id" <> "stock_adjustment_line"."location_id" and "stock_adjustment_line"."to_condition" is null and "stock_adjustment_line"."location_id" is not null and "stock_adjustment_line"."value_delta" is null)
        or ("stock_adjustment_line"."line_type" = 'OPENING' and "stock_adjustment_line"."quantity" > 0 and "stock_adjustment_line"."unit_cost" is not null and "stock_adjustment_line"."to_condition" is null and "stock_adjustment_line"."to_location_id" is null and "stock_adjustment_line"."location_id" is not null and "stock_adjustment_line"."value_delta" is null)
        or ("stock_adjustment_line"."line_type" = 'VALUE' and "stock_adjustment_line"."quantity" = 0 and "stock_adjustment_line"."value_delta" <> 0 and "stock_adjustment_line"."location_id" is null and "stock_adjustment_line"."to_condition" is null and "stock_adjustment_line"."to_location_id" is null and "stock_adjustment_line"."unit_cost" is null));